fn solve(input: Vec<char>) -> Vec<char> {
    // Get the first two characters as digits
    let first_digit = input[0].to_digit(10).unwrap();
    let second_digit = input[1].to_digit(10).unwrap();
    
    // Define the mapping from digit to good count
    let good_count = |digit: u32| -> u32 {
        match digit {
            0 => 2,
            1 => 7,
            2 => 2,
            3 => 3,
            4 => 3,
            5 => 4,
            6 => 2,
            7 => 5,
            8 => 1,
            9 => 2,
            _ => unreachable!(), // Should never happen since we have decimal digits
        }
    };
    
    // Calculate the product
    let product = good_count(first_digit) * good_count(second_digit);
    
    // Convert product to string and then to vector of chars
    let mut result: Vec<char> = product.to_string().chars().collect();
    
    // Append newline character
    result.push('\n');
    
    result
}